const user = $input.first().json;
const topics = user.interests || [];
if (topics.length === 0) return [];
return topics.map(topic => ({ json: { topic: topic.toLowerCase().trim(), user_id: user.id, user_email: user.email } }));

const topic = $('One Topic at a Time').item.json.topic;
const user_id = $('One Topic at a Time').item.json.user_id;
const user_email = $('One Topic at a Time').item.json.user_email;
const raw = $json?.output?.trim() || '';
const cleaned = raw.replace(/^"|"$/g, '').trim();

// Safety net: fall back to topic if AI dropped any word from the original topic
const topicWords = topic.toLowerCase().split(/\s+/);
const queryWords = cleaned.toLowerCase().split(/\s+/);
const isIncomplete = !cleaned || topicWords.some(w => !queryWords.includes(w));

const query = isIncomplete ? topic : cleaned;
return { json: { topic, query, user_id, user_email } };

const topic = $('One Topic at a Time').item.json.topic;
const user_id = $('One Topic at a Time').item.json.user_id;
const user_email = $('One Topic at a Time').item.json.user_email;
const articles = $json?.articles || [];

// Only keep the first (and only) valid article
const a = articles.find(a => a.url && a.title);

if (!a) {
  return { json: { _skip: true, topic, user_id, user_email, reason: 'no articles' } };
}

return {
  json: {
    _skip: false,
    source: `newsapi:${(a.source?.name || 'unknown').toLowerCase().replace(/\s+/g, '-')}`,
    source_id: a.source?.id || null,
    title: a.title,
    url: a.url,
    summary: a.description || null,
    content: a.content || null,
    published_at: a.publishedAt || null,
    tags: [topic],
    user_id,
    user_email
  }
};

